import time

def build_index(data):
    time.sleep(1)
    return {x: i for i, x in enumerate(data)}

RAW_DATA = [f'item_{i}' for i in range(1000)]

INDEX = None

def get_index():
    global INDEX
    if INDEX is None:
        INDEX = build_index(RAW_DATA)
    return INDEX

if __name__ == '__main__':
    INDEX = build_index(RAW_DATA)
    print('Index built:', len(INDEX))
    print('Sample:', INDEX['item_5'])

